const baseUrl = 'http://192.168.1.50:8800';//接口域名
// const baseUrl = 'http://192.168.1.6:8800'; //接口域名

const request = (options) => {
	return new Promise((resolve, reject) => {
		uni.request({
			url: baseUrl + options.url,
			method: options.method || "get",
			data: options.data || {},
			header: options.header || {},
			success: res => {
				resolve(res.data);
			},
			fail: err => {
				reject(err)
			},
			complete: () => {
				
			}
	
		})
	})
}
export default request
	